function qfactor(q){
  var t={'q2_k':0.3,'q3_k':0.4,'q4_k_m':0.5,'q4_0':0.55,'q4_k_s':0.5,'q5_k_m':0.65,'q6_k':0.75,'q8_0':1.0,'f16':2.0,'fp16':2.0,'f32':4.0,'fp32':4.0};
  var k=String(q||'').toLowerCase().replace(/[^a-z0-9_]/g,'');
  return t[k]||0.5;
}
function buildLocalSpec(o){
  o=o||{};
  var model=String(o.model||'').trim()||'（待填写模型）';
  var params=parseFloat(o.params); if(isNaN(params)||params<=0) params=7;
  var quant=String(o.quant||'Q4_K_M').trim()||'Q4_K_M';
  var ctx=parseInt(o.context,10); if(isNaN(ctx)||ctx<=0) ctx=8192;
  var vram=parseFloat(o.vram); if(isNaN(vram)||vram<=0) vram=16;
  var overhead=0.8;
  var weights=params*qfactor(quant);
  var ctxGB=ctx*params*2e-5;
  var total=weights+overhead+ctxGB;
  var fit= total<=vram;
  var rec;
  if(fit){ rec='当前 '+vram+'GB 显存可承载（估算占用 '+total.toFixed(1)+'GB，余量 '+(vram-total).toFixed(1)+'GB）。'; }
  else {
    var needQ=(vram-overhead-ctxGB)/params;
    var sug= needQ<=0.35?'Q2_K': needQ<=0.55?'Q4_K_M': needQ<=0.75?'Q6_K':'Q8_0';
    var sugCtx=Math.max(1024,Math.floor((vram-overhead-weights)/(params*2e-5)));
    rec='显存不足：估算占用 '+total.toFixed(1)+'GB > '+vram+'GB。建议降到 '+sug+' 或缩短上下文至约 '+sugCtx+' tokens。';
  }
  var lines=[];
  lines.push('# 本地模型部署规格：'+model);
  lines.push('');
  lines.push('## 一、配置输入');
  lines.push('- 模型：'+model);
  lines.push('- 参数量：'+params+'B');
  lines.push('- 量化：'+quant);
  lines.push('- 上下文窗口：'+ctx+' tokens');
  lines.push('- 目标硬件显存：'+vram+'GB');
  lines.push('');
  lines.push('## 二、显存估算（启发式，仅供参考）');
  lines.push('- 权重：'+weights.toFixed(1)+'GB（'+params+'B × '+qfactor(quant).toFixed(2)+' GB/B）');
  lines.push('- 运行时开销：'+overhead.toFixed(1)+'GB');
  lines.push('- 上下文(KV Cache)：'+ctxGB.toFixed(1)+'GB');
  lines.push('- 合计：'+total.toFixed(1)+'GB');
  lines.push('');
  lines.push('## 三、可行性结论');
  lines.push((fit?'- 状态：可部署':'- 状态：显存不足'));
  lines.push('- '+rec);
  lines.push('');
  lines.push('## 四、硬件建议');
  lines.push('- 显存 ≥ '+Math.ceil(total)+'GB（含余量）：消费级如 RTX 3060/4060(12-16G)、RTX 4080/4090(16-24G)、数据中心 A100/H100(40-80G)');
  lines.push('- 内存建议 ≥ 32GB；优先 NVMe 以加速模型加载');
  lines.push('- 推理运行时：llama.cpp / Ollama / LM Studio（均本地、零上传）');
  return {title:model+' 部署规格', fit:fit, totalGB:total, weightsGB:weights, ctxGB:ctxGB, recommendation:rec, markdown:lines.join('\n')};
}
var EXPORTS={qfactor:qfactor, buildLocalSpec:buildLocalSpec};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LocalModelSpecForgePure = EXPORTS; }
